mapper.select:
SELECT * FROM monitor_sys_gen_server_group
WHERE monitor_sys_gen_server_group_status = #{status}
ORDER BY monitor_sys_gen_server_group_sort ASC, create_time DESC

update.foreach:
UPDATE monitor_sys_gen_server_group
SET monitor_sys_gen_server_group_sort = #{group.monitorSysGenServerGroupSort}
WHERE monitor_sys_gen_server_group_id = #{group.monitorSysGenServerGroupId}

mapper.select:
SELECT COUNT(*) FROM monitor_sys_gen_server_group
WHERE monitor_sys_gen_server_group_name = #{groupName}

    AND monitor_sys_gen_server_group_id != #{excludeId}
